const statusTone = (value = '') => ({ Ativo: 'positive', Férias: 'warning', Ausente: 'danger', 'Contrato a terminar': 'warning', Pendente: 'warning', Aprovado: 'positive', Válido: 'positive', 'A expirar': 'warning', Aberto: 'warning', Resolvido: 'positive', Alta: 'danger', Média: 'warning', Baixa: 'positive' }[value] || 'neutral');

function readStore() { try { const raw = localStorage.getItem(STORAGE_KEY); return raw ? { ...seed, ...JSON.parse(raw) } : seed; } catch { return seed; } }
function persistStore(data) { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }
function Card({ children, className = '', onClick }) { return <div className={`suite-card ${className}`} onClick={onClick}>{children}</div>; }
function Badge({ children, tone }) { return <span className={`suite-badge ${tone || statusTone(String(children))}`}>{children}</span>; }
function Button({ children, variant = 'secondary', icon: Icon, onClick, type = 'button' }) { return <button type={type} className={`suite-btn ${variant}`} onClick={onClick}>{Icon && <Icon size={15} />}{children}</button>; }
function Modal({ title, children, onClose }) { return <div className="suite-overlay" role="dialog" aria-modal="true" aria-label={title}><div className="suite-modal"><div className="suite-modal-head"><strong>{title}</strong><button className="suite-icon-btn" onClick={onClose} aria-label="Fechar"><X size={18} /></button></div>{children}</div></div>; }
function Sparkline({ points, positive = true }) { const width = 460; const height = 130; const max = Math.max(...points); const min = Math.min(...points); const coords = points.map((point, index) => { const x = (index / (points.length - 1)) * width; const y = height - ((point - min) / Math.max(1, max - min)) * (height - 18) - 9; return [x, y]; }); const path = coords.map(([x, y], i) => `${i ? 'L' : 'M'} ${x.toFixed(2)} ${y.toFixed(2)}`).join(' '); const area = `${path} L ${width} ${height} L 0 ${height} Z`; return <svg className="suite-chart" viewBox={`0 0 ${width} ${height}`} aria-label="Gráfico de tendência"><defs><linearGradient id="tc-area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor={positive ? '#24a9ff' : '#ff7a7a'} stopOpacity=".24"/><stop offset="100%" stopColor={positive ? '#24a9ff' : '#ff7a7a'} stopOpacity="0"/></linearGradient></defs><path d={area} fill="url(#tc-area)"/><path d={path} fill="none" stroke={positive ? '#4dc4ff' : '#ff7a7a'} strokeWidth="3" strokeLinecap="round"/>{coords.map(([x, y], index) => <circle key={index} cx={x} cy={y} r="3.5" fill="#081a33" stroke={positive ? '#4dc4ff' : '#ff7a7a'} strokeWidth="2"/>)}</svg>; }
function Progress({ value }) { return <div className="suite-progress"><span style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>; }
function EmptyState({ title, description, icon: Icon = Search }) { return <div className="suite-empty"><Icon size={28}/><strong>{title}</strong><span>{description}</span></div>; }

export default function TeconnectSuite({ profile }) {
  const [data, setData] = useState(readStore);
  const [page, setPage] = useState('overview');
  const [theme, setTheme] = useState(() => localStorage.getItem('teconnect-suite-theme') || 'dark');
  const [query, setQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('Todos');
  const [statusFilter, setStatusFilter] = useState('Todos');
  const [modal, setModal] = useState(null);
  const [toast, setToast] = useState(null);
  const [assistantInput, setAssistantInput] = useState('');
  const [assistantMessages, setAssistantMessages] = useState([{ from: 'assistant', text: 'Olá. Sou o Te-connect Assist. Posso investigar a operação, criar tarefas e preparar resumos com os dados desta demonstração.' }]);
  const [notificationFilter, setNotificationFilter] = useState('Todas');
  const [realtimePulse, setRealtimePulse] = useState(0);

  useEffect(() => persistStore(data), [data]);
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('teconnect-suite-theme', theme); }, [theme]);
  useEffect(() => { const interval = setInterval(() => setRealtimePulse((value) => value + 1), 8000); return () => clearInterval(interval); }, []);

  const notify = (message, kind = 'ok') => { setToast({ message, kind }); window.clearTimeout(window.__tcSuiteToast); window.__tcSuiteToast = window.setTimeout(() => setToast(null), 3000); };
  const update = (key, next) => setData((current) => ({ ...current, [key]: typeof next === 'function' ? next(current[key]) : next }));
  const activeCount = data.employees.filter((employee) => employee.status === 'Ativo').length;
  const presentCount = data.attendance.filter((row) => row.date === today() && row.status === 'Presente').length;
  const lateCount = data.attendance.filter((row) => row.date === today() && row.late > 0).length;
  const pendingCount = data.tasks.filter((task) => task.status !== 'Concluída').length + data.vacations.filter((item) => item.status === 'Pendente').length;
  const unreadCount = data.notifications.filter((item) => item.unread).length;
  const currentMeta = pageMeta[page];
  const filteredEmployees = useMemo(() => data.employees.filter((employee) => { const matchesQuery = `${employee.name} ${employee.role} ${employee.team} ${employee.email}`.toLowerCase().includes(query.toLowerCase()); const matchesRole = roleFilter === 'Todos' || employee.role === roleFilter; const matchesStatus = statusFilter === 'Todos' || employee.status === statusFilter; return matchesQuery && matchesRole && matchesStatus; }), [data.employees, query, roleFilter, statusFilter]);

  const openEmployeeForm = (employee = null) => setModal({ type: 'employee', item: employee });
  const openCandidateForm = () => setModal({ type: 'candidate' });
  const openTaskForm = () => setModal({ type: 'task' });
  const saveEmployee = (form) => { const item = { ...form, id: form.id || uid('emp'), vacationBalance: Number(form.vacationBalance || 0), performance: Number(form.performance || 80) }; update('employees', (items) => form.id ? items.map((row) => row.id === form.id ? item : row) : [item, ...items]); notify(form.id ? 'Colaborador atualizado.' : 'Colaborador criado com sucesso.'); setModal(null); };
  const saveCandidate = (form) => { const item = { ...form, id: uid('cand'), score: Number(form.score || 80), criteria: { experience: Number(form.experience || 80), roleFit: Number(form.roleFit || 80), interview: Number(form.interview || 80) } }; update('candidates', (items) => [item, ...items]); notify('Candidatura adicionada ao pipeline.'); setModal(null); };
  const saveTask = (form) => { update('tasks', (items) => [{ ...form, id: uid('task'), status: 'Aberto' }, ...items]); notify('Tarefa criada e atribuída.'); setModal(null); };
  const archiveEmployee = (id) => { update('employees', (items) => items.map((item) => item.id === id ? { ...item, status: 'Arquivado' } : item)); notify('Colaborador arquivado.'); };
  const reactivateEmployee = (id) => { update('employees', (items) => items.map((item) => item.id === id ? { ...item, status: 'Ativo' } : item)); notify('Colaborador reativado.'); };
  const toggleOnboardingTask = (onboardingId, taskIndex) => update('onboarding', (items) => items.map((item) => item.id !== onboardingId ? item : { ...item, tasks: item.tasks.map((task, index) => index !== taskIndex ? task : { ...task, done: !task.done }) }));
  const resolveAlert = (id) => { update('alerts', (items) => items.map((item) => item.id === id ? { ...item, status: 'Resolvido' } : item)); notify('Alerta marcado como resolvido.'); };
  const markNotification = (id) => update('notifications', (items) => items.map((item) => item.id === id ? { ...item, unread: false } : item));

  const handlePunch = (type) => {
    const existing = data.attendance.find((row) => row.employee === profile?.full_name);
    const now = new Date().toLocaleTimeString('pt-PT', { hour: '2-digit', minute: '2-digit' });
    if (type === 'entry') {
      if (existing?.entry) return notify('A entrada de hoje já está registada.', 'warning');
      const row = existing || { id: uid('att'), employee: profile?.full_name || 'Utilizador Te-connect', team: 'Recursos Humanos', date: today(), entry: null, pause: null, resume: null, exit: null, status: 'Presente', late: 0, extra: 0 };
      update('attendance', (items) => existing ? items.map((item) => item.id === existing.id ? { ...item, entry: now, status: 'Presente' } : item) : [row, ...items]);
      notify('Entrada registada com sucesso.');
    } else {
      if (!existing) return notify('Registe a entrada antes de iniciar esta ação.', 'warning');
      const field = type === 'pause' ? 'pause' : type === 'resume' ? 'resume' : 'exit';
      update('attendance', (items) => items.map((item) => item.id === existing.id ? { ...item, [field]: now, status: type === 'exit' ? 'Saída' : 'Presente' } : item));
      notify(type === 'pause' ? 'Pausa iniciada.' : type === 'resume' ? 'Pausa terminada.' : 'Saída registada.');
    }
  };

  const exportReport = () => { const rows = [['Nome','Função','Equipa','Estado','Férias disponíveis'], ...data.employees.map((item) => [item.name,item.role,item.team,item.status,item.vacationBalance])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"','""')}"`).join(';')).join('\n'); const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `te-connect-rh-${today()}.csv`; link.click(); URL.revokeObjectURL(url); notify('Relatório exportado para CSV.'); };
  const assistantReply = (input) => { const text = input.toLowerCase(); if (text.includes('férias')) return 'Esta semana há pedidos e ausências relevantes. Carolina Silva está de férias e Ana Martins tem um pedido pendente para 21–24 setembro.'; if (text.includes('atras')) return `Foram identificados ${lateCount} atrasos hoje. Bruno Almeida tem 4 ocorrências nos últimos 14 dias e merece investigação.`; if (text.includes('document')) return `Há ${data.documents.filter((item) => item.status === 'A expirar').length} documentos a expirar em breve: Eva Rodrigues e Hugo Carvalho.`; if (text.includes('risco')) return 'Os sinais prioritários são documentação próxima da expiração, atrasos recorrentes e cobertura de Operações a 86%.'; if (text.includes('cobertura')) return 'A equipa de Operações está com 86% de cobertura no turno atual. Existe uma lacuna no período das 14h.'; if (text.includes('onboarding')) return 'Sugestão: concluir o acesso ao portal de Marta Lopes e preparar a apresentação à equipa de Gabriela Ferreira.'; return 'Posso consultar férias, atrasos, documentos, cobertura, onboarding e riscos. Também posso criar uma tarefa a partir do resultado.'; };
  const askAssistant = () => { const input = assistantInput.trim(); if (!input) return; setAssistantMessages((messages) => [...messages, { from: 'user', text: input }, { from: 'assistant', text: assistantReply(input) }]); setAssistantInput(''); };
  const resetDemo = () => { localStorage.removeItem(STORAGE_KEY); setData(seed); notify('Dados de demonstração repostos.'); };

  const renderOverview = () => <>
    <div className="suite-hero-grid"><Card className="suite-hero-card"><div className="suite-eyebrow"><Sparkles size={14}/> Executive People Command</div><h1>Tudo o que o RH precisa, numa só visão.</h1><p>Operação humana, estratégia e sinais críticos reunidos num centro de controlo moderno.</p><div className="suite-actions"><Button variant="primary" icon={RefreshCw} onClick={() => notify('Dados sincronizados com sucesso.')}>Sincronizar dados</Button><Button icon={Download} onClick={exportReport}>Exportar relatório</Button><Button icon={UserPlus} onClick={() => openEmployeeForm()}>Criar colaborador</Button></div></Card><Card className="suite-hero-side"><div className="suite-hero-side-top"><div><span className="suite-kicker">Tempo real</span><strong>Ativo</strong></div><div className="suite-live-dot"><span/></div></div><div className="suite-mini-stat"><span>Última sincronização</span><strong>{realtimePulse % 2 ? 'agora' : 'há poucos segundos'}</strong></div><div className="suite-mini-stat"><span>Ambiente</span><strong>Demo persistente</strong></div></Card></div>
    <div className="suite-kpis">{[['Colaboradores ativos',activeCount,Users,'de 8 no ambiente de demonstração'],['Presentes agora',presentCount,UserCheck,`${presentCount} registos em tempo real`],['Atrasos hoje',lateCount,Clock3,'priorizar Bruno Almeida'],['Férias',data.vacations.filter((item) => item.status === 'Pendente').length,CalendarDays,'pedidos por aprovar'],['Horas extra','2h 41m',TrendingUp,'últimos 7 dias'],['Pendências',pendingCount,ClipboardList,'tarefas e aprovações']].map(([label,value,Icon,foot]) => <Card key={label} className="suite-kpi"><div className="suite-kpi-top"><span>{label}</span><Icon size={17}/></div><strong>{value}</strong><span>{foot}</span></Card>)}</div>
    <div className="suite-two-col"><Card className="suite-panel suite-chart-panel"><div className="suite-panel-head"><div><h2>Assiduidade</h2><span>Últimos 7 dias · 94% média</span></div><Badge tone="positive">Estável</Badge></div><Sparkline points={[88,91,90,93,92,95,94]}/><div className="suite-chart-labels"><span>11 Set</span><span>12 Set</span><span>13 Set</span><span>14 Set</span><span>15 Set</span><span>16 Set</span><span>Hoje</span></div></Card><Card className="suite-panel"><div className="suite-panel-head"><div><h2>Centro de alertas</h2><span>Prioridades para o RH</span></div><Button onClick={() => setPage('notifications')}>Ver todos</Button></div><div className="suite-alert-stack">{data.alerts.slice(0,3).map((alert) => <div className="suite-alert-row" key={alert.id}><div className={`suite-alert-icon ${statusTone(alert.severity)}`}><AlertTriangle size={16}/></div><div className="suite-row-main"><strong>{alert.title}</strong><span>{alert.message}</span></div><Badge>{alert.severity}</Badge></div>)}</div></Card></div>
    <div className="suite-two-col"><Card className="suite-panel"><div className="suite-panel-head"><div><h2>Resumo executivo</h2><span>Recomendações acionáveis</span></div><ShieldCheck size={18}/></div><div className="suite-recommendation"><CircleCheck size={18}/><div><strong>Manter a estabilidade de presença</strong><span>A assiduidade média está em 94% e sem tendência de deterioração.</span></div></div><div className="suite-recommendation warning"><CircleAlert size={18}/><div><strong>Investigar atrasos recorrentes</strong><span>Bruno Almeida concentra 4 atrasos nos últimos 14 dias.</span></div></div><div className="suite-recommendation warning"><FileText size={18}/><div><strong>Antecipar conformidade documental</strong><span>Existem documentos que expiram nos próximos 15 dias.</span></div></div></Card><Card className="suite-panel"><div className="suite-panel-head"><div><h2>Atalhos do RH</h2><span>Ações frequentes</span></div></div><div className="suite-shortcuts"><button onClick={() => openEmployeeForm()}><UserPlus size={18}/>Novo colaborador</button><button onClick={() => setPage('recruitment')}><BriefcaseBusiness size={18}/>Nova candidatura</button><button onClick={() => setPage('vacations')}><CalendarCheck size={18}/>Aprovar férias</button><button onClick={() => setPage('documents')}><Upload size={18}/>Carregar documento</button></div></Card></div>
  </>;

  const renderPeople = () => <><div className="suite-section-head"><div><h2>Colaboradores</h2><span>{data.employees.length} registos</span></div><Button variant="primary" icon={UserPlus} onClick={() => openEmployeeForm()}>Novo colaborador</Button></div><Card className="suite-toolbar"><div className="suite-search"><Search size={17}/><input aria-label="Pesquisar colaboradores" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Pesquisar por nome, função, equipa ou email"/></div><select value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)}><option>Todos</option>{[...new Set(data.employees.map((e) => e.role))].map((role) => <option key={role}>{role}</option>)}</select><select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}><option>Todos</option>{['Ativo','Férias','Ausente','Contrato a terminar','Arquivado'].map((status) => <option key={status}>{status}</option>)}</select><Button icon={Filter} onClick={() => notify('Filtros aplicados.')}>Filtros</Button></Card><Card className="suite-panel table-wrap"><table className="suite-table"><thead><tr><th>Colaborador</th><th>Função</th><th>Equipa</th><th>Contrato</th><th>Estado</th><th>Férias</th><th/></tr></thead><tbody>{filteredEmployees.length ? filteredEmployees.map((employee) => <tr key={employee.id}><td><button className="suite-person-cell" onClick={() => setModal({ type:'employee-detail', item:employee })}><span className="suite-avatar">{initials(employee.name)}</span><span><strong>{employee.name}</strong><small>{employee.email}</small></span></button></td><td>{employee.role}</td><td>{employee.team}</td><td>{employee.contract}</td><td><Badge>{employee.status}</Badge></td><td>{employee.vacationBalance} dias</td><td><button className="suite-icon-btn" aria-label="Editar" onClick={() => openEmployeeForm(employee)}><Pencil size={15}/></button></td></tr>) : <tr><td colSpan="7"><EmptyState title="Nenhum colaborador encontrado" description="Ajuste a pesquisa ou crie um novo colaborador."/></td></tr>}</tbody></table></Card></>;

  const renderRecruitment = () => <><div className="suite-section-head"><div><h2>Pipeline de recrutamento</h2><span>Critérios transparentes: experiência, aderência à função e entrevista.</span></div><Button variant="primary" icon={Plus} onClick={openCandidateForm}>Adicionar candidato</Button></div><Card className="suite-note"><ShieldCheck size={17}/><span>O ranking usa apenas critérios profissionais documentados. Não são usados dados sensíveis ou atributos protegidos.</span></Card><div className="suite-kanban">{['Candidatura','Triagem','Entrevista','Proposta','Contratado','Rejeitado'].map((stage) => <div className="suite-kanban-col" key={stage}><div className="suite-kanban-head"><strong>{stage}</strong><span>{data.candidates.filter((c) => c.stage === stage).length}</span></div>{data.candidates.filter((c) => c.stage === stage).map((candidate) => <Card className="suite-candidate-card" key={candidate.id}><div className="suite-candidate-top"><span className="suite-avatar">{initials(candidate.name)}</span><Badge tone="positive">{candidate.score} pts</Badge></div><strong>{candidate.name}</strong><span>{candidate.role}</span><small>{candidate.source} · {candidate.nextInterview ? `Entrevista ${formatDate(candidate.nextInterview)}` : 'Sem entrevista marcada'}</small><div className="suite-score-row"><span>Experiência</span><strong>{candidate.criteria.experience}%</strong></div><Progress value={candidate.criteria.experience}/><button className="suite-text-btn" onClick={() => setModal({ type:'candidate-detail', item:candidate })}>Ver candidato <ArrowRight size={14}/></button></Card>)}</div>)}</div></>;

  const renderOnboarding = () => <><div className="suite-section-head"><div><h2>Onboarding por colaborador</h2><span>Checklist, responsáveis e tarefas em atraso.</span></div><Button variant="primary" icon={Plus} onClick={() => notify('Pode iniciar um novo onboarding a partir de uma contratação no pipeline.')}>Novo onboarding</Button></div><div className="suite-grid-2">{data.onboarding.map((item) => <Card className="suite-panel" key={item.id}><div className="suite-panel-head"><div><h3>{item.employee}</h3><span>{item.role} · prazo {formatDate(item.due)}</span></div><Badge tone={item.progress >= 80 ? 'positive' : 'warning'}>{item.progress}%</Badge></div><Progress value={item.progress}/><div className="suite-checklist">{item.tasks.map((task, index) => <label key={task.label} className={task.done ? 'done' : ''}><input type="checkbox" checked={task.done} onChange={() => toggleOnboardingTask(item.id,index)}/><span>{task.label}</span><small>{task.owner}</small></label>)}</div></Card>)}</div></>;

  const renderAttendance = () => <><div className="suite-section-head"><div><h2>Registo de ponto</h2><span>Simulação funcional de entrada, pausa, retoma e saída.</span></div><div className="suite-actions"><Button icon={FileText} onClick={exportReport}>Relatório</Button><Button variant="primary" icon={Clock3} onClick={() => handlePunch('entry')}>Registar entrada</Button></div></div><div className="suite-clock-grid"><Card className="suite-clock-card"><div className="suite-clock-title"><Clock3 size={19}/> O meu ponto</div><div className="suite-clock-time">{new Intl.DateTimeFormat('pt-PT',{hour:'2-digit',minute:'2-digit'}).format(new Date())}</div><div className="suite-clock-actions"><Button onClick={() => handlePunch('entry')}>Entrada</Button><Button onClick={() => handlePunch('pause')}>Pausa</Button><Button onClick={() => handlePunch('resume')}>Retomar</Button><Button variant="danger" onClick={() => handlePunch('exit')}>Saída</Button></div></Card><Card className="suite-clock-card"><div className="suite-clock-title"><MapPin size={19}/> Geofence</div><strong>Escritório Lisboa · dentro do perímetro</strong><span className="suite-muted">Raio configurado: 150 m · localização simulada.</span><Badge tone="positive">Válido</Badge></Card></div><Card className="suite-panel table-wrap"><div className="suite-panel-head"><div><h2>Registos de hoje</h2><span>{data.attendance.length} colaboradores acompanhados</span></div></div><table className="suite-table"><thead><tr><th>Colaborador</th><th>Entrada</th><th>Pausa</th><th>Retoma</th><th>Saída</th><th>Atraso</th><th>Extra</th><th>Estado</th></tr></thead><tbody>{data.attendance.map((row) => <tr key={row.id}><td>{row.employee}</td><td>{row.entry || '—'}</td><td>{row.pause || '—'}</td><td>{row.resume || '—'}</td><td>{row.exit || '—'}</td><td>{row.late ? `${row.late} min` : '—'}</td><td>{row.extra ? `${row.extra} min` : '—'}</td><td><Badge tone={row.status === 'Presente' ? 'positive' : 'warning'}>{row.status}</Badge></td></tr>)}</tbody></table></Card></>;

  const renderShifts = () => <><div className="suite-section-head"><div><h2>Horários e turnos</h2><span>Cobertura, conflitos e publicação semanal.</span></div><Button variant="primary" icon={Plus} onClick={() => setModal({ type:'shift' })}>Criar turno</Button></div><div className="suite-grid-2">{data.shifts.map((shift) => <Card className="suite-panel" key={shift.id}><div className="suite-panel-head"><div><h3>{shift.name}</h3><span>{shift.team} · {shift.days}</span></div><Badge tone={shift.published ? 'positive' : 'warning'}>{shift.published ? 'Publicado' : 'Rascunho'}</Badge></div><div className="suite-shift-metrics"><div><span>Cobertura</span><strong>{shift.coverage}%</strong></div><div><span>Conflitos</span><strong>{shift.conflicts}</strong></div><div><span>Trocas</span><strong>{shift.conflicts + 1}</strong></div></div><Progress value={shift.coverage}/><div className="suite-actions"><Button onClick={() => notify('Editor de turno aberto.')}>Editar</Button><Button onClick={() => update('shifts',(items) => items.map((item) => item.id === shift.id ? { ...item, published:true } : item))}>Publicar</Button></div></Card>)}</div></>;

  const renderVacations = () => <><div className="suite-section-head"><div><h2>Férias e ausências</h2><span>Pedidos, saldos e cobertura da equipa.</span></div><Button variant="primary" icon={Plus} onClick={() => setModal({ type:'vacation' })}>Novo pedido</Button></div><div className="suite-grid-4">{data.employees.slice(0,4).map((employee) => <Card className="suite-kpi compact" key={employee.id}><div className="suite-kpi-top"><span>{employee.name}</span><CalendarCheck size={16}/></div><strong>{employee.vacationBalance}</strong><span>dias disponíveis</span></Card>)}</div><Card className="suite-panel table-wrap"><table className="suite-table"><thead><tr><th>Colaborador</th><th>Tipo</th><th>Período</th><th>Dias</th><th>Estado</th><th/></tr></thead><tbody>{data.vacations.map((item) => <tr key={item.id}><td>{item.employee}</td><td>{item.type}</td><td>{formatDate(item.start)} → {formatDate(item.end)}</td><td>{item.days}</td><td><Badge>{item.status}</Badge></td><td>{item.status === 'Pendente' && <div className="suite-inline-actions"><button className="suite-icon-btn" onClick={() => { update('vacations',(items) => items.map((row) => row.id === item.id ? { ...row, status:'Aprovado' } : row)); notify('Pedido aprovado.'); }}><Check size={15}/></button><button className="suite-icon-btn danger" onClick={() => { update('vacations',(items) => items.map((row) => row.id === item.id ? { ...row, status:'Rejeitado' } : row)); notify('Pedido rejeitado.'); }}><X size={15}/></button></div>}</td></tr>)}</tbody></table></Card></>;

  const renderDocuments = () => <><div className="suite-section-head"><div><h2>Documentos e conformidade</h2><span>Validade, alertas e histórico documental.</span></div><Button variant="primary" icon={Upload} onClick={() => setModal({ type:'document' })}>Carregar documento</Button></div><div className="suite-grid-3">{data.documents.map((document) => <Card className="suite-panel" key={document.id}><div className="suite-document-icon"><FileText size={18}/></div><div className="suite-panel-head"><div><h3>{document.type}</h3><span>{document.employee}</span></div><Badge>{document.status}</Badge></div><div className="suite-doc-date">Validade <strong>{formatDate(document.expiry)}</strong></div><div className="suite-actions"><Button icon={Eye} onClick={() => notify(`Abrir pré-visualização de ${document.type}.`)}>Abrir</Button><Button icon={Bell} onClick={() => notify('Lembrete agendado.')}>Lembrar</Button></div></Card>)}</div></>;

  const renderPerformance = () => <><div className="suite-section-head"><div><h2>Desempenho e desenvolvimento</h2><span>Objetivos, competências, feedback e PDI.</span></div><Button variant="primary" icon={Plus} onClick={() => setModal({ type:'goal' })}>Novo objetivo</Button></div><div className="suite-grid-3">{data.goals.map((goal) => <Card className="suite-panel" key={goal.id}><div className="suite-panel-head"><div><h3>{goal.title}</h3><span>{goal.employee} · {goal.cycle}</span></div><Target size={18}/></div><Progress value={goal.progress}/><div className="suite-score-row"><span>Progresso</span><strong>{goal.progress}%</strong></div><span className="suite-muted">Responsável: {goal.owner}</span></Card>)}</div><div className="suite-two-col"><Card className="suite-panel"><div className="suite-panel-head"><div><h2>Competências</h2><span>Visão consolidada</span></div><BarChart3 size={18}/></div>{[['Liderança',88],['Comunicação',91],['Colaboração',94],['Gestão de tempo',82]].map(([label,value]) => <div className="suite-skill" key={label}><div><span>{label}</span><strong>{value}%</strong></div><Progress value={value}/></div>)}</Card><Card className="suite-panel"><div className="suite-panel-head"><div><h2>PDI</h2><span>Plano de Desenvolvimento Individual</span></div><BookOpen size={18}/></div><div className="suite-recommendation"><CircleCheck size={18}/><div><strong>Formação em feedback estruturado</strong><span>Objetivo: reforçar liderança e alinhamento.</span></div></div><div className="suite-recommendation"><CircleCheck size={18}/><div><strong>Mentoria cruzada</strong><span>Emparelhar People + Operações durante 6 semanas.</span></div></div></Card></div></>;

  const renderIntelligence = () => <><div className="suite-intelligence-hero"><div><div className="suite-eyebrow"><BrainCircuit size={15}/> Intelligence Center</div><h2>Antecipe. Decida. Aja.</h2><p>Os sinais abaixo são derivados apenas dos dados da demonstração e mostram sempre a origem do indicador.</p></div><Button variant="primary" icon={Sparkles} onClick={() => notify('Resumo executivo gerado com sucesso.')}>Gerar resumo</Button></div><div className="suite-grid-3">{[['Atrasos recorrentes',72,'4 ocorrências em Bruno Almeida · fonte: registos de ponto','Investigar'],['Documentação',88,'2 documentos próximos da expiração · fonte: base documental','Criar ação'],['Cobertura de equipa',68,'Operações 86% · fonte: turnos publicados','Atribuir responsável'],['Férias concentradas',55,'RH com sobreposição prevista · fonte: calendário','Investigar'],['Horas extra',61,'2h41m últimos 7 dias · fonte: assiduidade','Criar ação'],['Rotatividade',39,'1 contrato a terminar · fonte: colaboradores','Acompanhar']].map(([label,score,detail,action]) => <Card className="suite-panel intelligence-card" key={label}><div className="intelligence-meter" style={{ '--value': `${score}%` }}><div>{score}</div></div><div><h3>{label}</h3><span>{detail}</span></div><Button onClick={() => notify(`${action}: ${label}.`)}>{action}</Button></Card>)}</div><Card className="suite-note"><ShieldCheck size={17}/><span>As recomendações desta demonstração são explicáveis e não usam características sensíveis.</span></Card></>;

  const renderAssistant = () => <div className="suite-assistant-grid"><Card className="suite-panel assistant-chat"><div className="suite-panel-head"><div><h2>Te-connect Assist</h2><span>Assistente de RH contextual</span></div><Badge tone="positive">Online</Badge></div><div className="assistant-messages">{assistantMessages.map((message,index) => <div className={`assistant-message ${message.from}`} key={index}><span>{message.from === 'assistant' ? <Sparkles size={14}/> : <UserRound size={14}/>}</span><p>{message.text}</p></div>)}</div><form className="assistant-input" onSubmit={(event) => { event.preventDefault(); askAssistant(); }}><input value={assistantInput} onChange={(event) => setAssistantInput(event.target.value)} placeholder="Ex.: quais documentos expiram este mês?" aria-label="Pergunta ao Te-connect Assist"/><Button type="submit" variant="primary" icon={Send}>Enviar</Button></form></Card><Card className="suite-panel"><div className="suite-panel-head"><div><h2>Atalhos inteligentes</h2><span>Perguntas frequentes</span></div><MessageCircle size={18}/></div><div className="suite-assistant-actions">{['Quem tem férias esta semana?','Mostra os atrasos recorrentes.','Quais documentos expiram este mês?','Resume os principais riscos de RH.','Quais equipas têm menos cobertura amanhã?','Prepara um relatório de assiduidade.'].map((item) => <button key={item} onClick={() => { setAssistantInput(item); setTimeout(() => { const text = item; setAssistantMessages((messages) => [...messages,{from:'user',text},{from:'assistant',text:assistantReply(text)}]); setAssistantInput(''); },0); }}>{item}<ChevronRight size={15}/></button>)}</div><div className="suite-recommendation"><Sparkles size={18}/><div><strong>Tarefa sugerida para hoje</strong><span>Validar documentos que expiram nos próximos 15 dias.</span><Button icon={Plus} onClick={openTaskForm}>Criar tarefa</Button></div></div></Card></div>;

  const renderNotifications = () => { const notifications = data.notifications.filter((item) => notificationFilter === 'Todas' || (notificationFilter === 'Não lidas' ? item.unread : item.module === notificationFilter)); return <><div className="suite-section-head"><div><h2>Central de notificações</h2><span>{unreadCount} por ler</span></div><Button icon={Check} onClick={() => update('notifications',(items) => items.map((item) => ({ ...item, unread:false })))}>Marcar todas como lidas</Button></div><Card className="suite-toolbar"><Filter size={16}/><select value={notificationFilter} onChange={(e) => setNotificationFilter(e.target.value)}><option>Todas</option><option>Não lidas</option><option>Férias</option><option>Documentos</option><option>Escalas</option></select></Card><Card className="suite-panel"><div className="notification-list">{notifications.map((item) => <div className={`notification-row ${item.unread ? 'unread' : ''}`} key={item.id}><div className="suite-notification-icon"><Bell size={16}/></div><div className="suite-row-main"><strong>{item.title}</strong><span>{item.message}</span><small>{item.module} · {item.time}</small></div><div className="suite-inline-actions"><button className="suite-icon-btn" onClick={() => markNotification(item.id)}><Check size={15}/></button><button className="suite-icon-btn" onClick={() => notify(`Detalhe aberto: ${item.title}.`)}><Eye size={15}/></button></div></div>)}</div></Card></> };

  const renderPage = () => ({ overview:renderOverview, people:renderPeople, recruitment:renderRecruitment, onboarding:renderOnboarding, attendance:renderAttendance, shifts:renderShifts, vacations:renderVacations, documents:renderDocuments, performance:renderPerformance, intelligence:renderIntelligence, assistant:renderAssistant, notifications:renderNotifications }[page] || renderOverview)();

  return <div className="suite-app"><aside className="suite-sidebar"><div className="suite-brand-wrap"><div className="tc-brand-mark" aria-label="Te-connect"/></div><div className="suite-org"><div className="suite-org-icon"><Building2 size={17}/></div><div><strong>{profile?.company_name || 'Te-connect Demo'}</strong><span>{profile?.role || 'ADMINISTRADOR'} · Ambiente seguro</span></div></div><nav className="suite-nav" aria-label="Navegação principal">{navGroups.map((group) => <div key={group.label}><div className="suite-nav-label">{group.label}</div>{group.items.map((id) => { const [label,,Icon] = pageMeta[id]; return <button key={id} className={page === id ? 'active' : ''} onClick={() => setPage(id)}><Icon size={17}/><span>{label}</span>{id === 'notifications' && unreadCount > 0 && <em>{unreadCount}</em>}</button>; })}</div>)}</nav><div className="suite-sidebar-bottom"><button onClick={() => setTheme((value) => value === 'dark' ? 'light' : 'dark')}>{theme === 'dark' ? <Sun size={16}/> : <Moon size={16}/>} {theme === 'dark' ? 'Modo claro' : 'Modo escuro'}</button><button onClick={resetDemo}><RefreshCw size={16}/>Repor demonstração</button></div></aside><main className="suite-main"><header className="suite-topbar"><div className="suite-top-left"><button className="suite-mobile-menu" onClick={() => notify('Em ecrãs pequenos, deslize para abrir o menu lateral.') }><Menu size={18}/></button><div className="suite-breadcrumb">Te-connect <ChevronRight size={14}/><strong>{currentMeta[0]}</strong></div></div><div className="suite-top-right"><div className="suite-live"><span/>Tempo real ativo</div><button className="suite-top-search" onClick={() => setPage('people')}><Search size={15}/>Pesquisar <kbd>⌘K</kbd></button><button className="suite-top-icon" aria-label="Notificações" onClick={() => setPage('notifications')}><Bell size={17}/>{unreadCount > 0 && <i>{unreadCount}</i>}</button><div className="suite-user-chip"><span className="suite-avatar small">{initials(profile?.full_name || 'TC')}</span><span><strong>{profile?.full_name || 'Administrador'}</strong><small>{profile?.role || 'RH'}</small></span></div></div></header><div className="suite-content"><div className="suite-page-intro"><div><div className="suite-eyebrow"><Sparkles size={14}/> {currentMeta[0]}</div><h1>{currentMeta[1]}</h1><p>{page === 'overview' ? 'Centro executivo com indicadores, recomendações e ações rápidas para o dia a dia.' : pageMeta[page][1]}</p></div><div className="suite-page-meta"><span><ShieldCheck size={14}/> Dados demonstrativos persistentes</span><span><CircleCheck size={14}/> UX pronta para evolução para API</span></div></div>{renderPage()}</div></main>{toast && <div className={`suite-toast ${toast.kind}`}><CheckCircle2 size={16}/>{toast.message}</div>}{modal?.type === 'employee' && <EmployeeForm employee={modal.item} onClose={() => setModal(null)} onSave={saveEmployee}/>} {modal?.type === 'employee-detail' && <EmployeeDetail employee={modal.item} onClose={() => setModal(null)} onArchive={archiveEmployee} onReactivate={reactivateEmployee}/>} {modal?.type === 'candidate' && <CandidateForm onClose={() => setModal(null)} onSave={saveCandidate}/>} {modal?.type === 'candidate-detail' && <CandidateDetail candidate={modal.item} onClose={() => setModal(null)} onAdvance={(stage) => { update('candidates',(items) => items.map((item) => item.id === modal.item.id ? { ...item, stage } : item)); setModal(null); notify(`Candidato movido para ${stage}.`); }}/>} {modal?.type === 'task' && <TaskForm onClose={() => setModal(null)} onSave={saveTask}/>} {modal?.type === 'shift' && <ShiftForm onClose={() => setModal(null)} onSave={(form) => { update('shifts',(items) => [{ ...form,id:uid('shift'),coverage:100,conflicts:0,published:false },...items]); setModal(null); notify('Novo turno criado.'); }}/>} {modal?.type === 'vacation' && <VacationForm employees={data.employees} onClose={() => setModal(null)} onSave={(form) => { update('vacations',(items) => [{ ...form,id:uid('vac'),status:'Pendente' },...items]); setModal(null); notify('Pedido submetido para aprovação.'); }}/>} {modal?.type === 'document' && <DocumentForm employees={data.employees} onClose={() => setModal(null)} onSave={(form) => { update('documents',(items) => [{ ...form,id:uid('doc'),status:'Válido' },...items]); setModal(null); notify('Documento adicionado à base documental.'); }}/>} {modal?.type === 'goal' && <GoalForm employees={data.employees} onClose={() => setModal(null)} onSave={(form) => { update('goals',(items) => [{ ...form,id:uid('goal'),progress:Number(form.progress || 0) },...items]); setModal(null); notify('Objetivo criado.'); }}/>}</div>;
}

function Field({ label, children, required = false }) { return <label className="suite-field"><span>{label}{required ? ' *' : ''}</span>{children}</label>; }
function EmployeeForm({ employee, onClose, onSave }) { const [form,setForm]=useState(employee || {name:'',role:'',team:'',status:'Ativo',contract:'Efetivo',email:'',phone:'',hireDate:today(),vacationBalance:22,performance:80,location:'Lisboa'}); const patch=(key,value)=>setForm((current)=>({...current,[key]:value})); return <Modal title={employee ? 'Editar colaborador' : 'Novo colaborador'} onClose={onClose}><form className="suite-form" onSubmit={(event)=>{event.preventDefault();if(!form.name||!form.role||!form.email)return;onSave(form)}}><div className="suite-form-grid"><Field label="Nome" required><input value={form.name} onChange={(e)=>patch('name',e.target.value)}/></Field><Field label="Função" required><input value={form.role} onChange={(e)=>patch('role',e.target.value)}/></Field><Field label="Equipa"><input value={form.team} onChange={(e)=>patch('team',e.target.value)}/></Field><Field label="Contrato"><select value={form.contract} onChange={(e)=>patch('contract',e.target.value)}><option>Efetivo</option><option>Termo</option><option>Estágio</option></select></Field><Field label="Email" required><input type="email" value={form.email} onChange={(e)=>patch('email',e.target.value)}/></Field><Field label="Telefone"><input value={form.phone} onChange={(e)=>patch('phone',e.target.value)}/></Field><Field label="Estado"><select value={form.status} onChange={(e)=>patch('status',e.target.value)}><option>Ativo</option><option>Férias</option><option>Ausente</option><option>Contrato a terminar</option></select></Field><Field label="Dias de férias"><input type="number" min="0" value={form.vacationBalance} onChange={(e)=>patch('vacationBalance',e.target.value)}/></Field></div><div className="suite-modal-actions"><Button onClick={onClose}>Cancelar</Button><Button type="submit" variant="primary">Guardar</Button></div></form></Modal> }
function EmployeeDetail({ employee,onClose,onArchive,onReactivate }){return <Modal title={employee.name} onClose={onClose}><div className="suite-profile-head"><span className="suite-avatar xl">{initials(employee.name)}</span><div><h3>{employee.role}</h3><span>{employee.team} · {employee.location}</span><div className="suite-inline-badges"><Badge>{employee.status}</Badge><Badge tone="neutral">{employee.contract}</Badge></div></div></div><div className="suite-detail-grid"><div><span>Contacto</span><strong>{employee.email}</strong><small>{employee.phone}</small></div><div><span>Entrada na empresa</span><strong>{formatDate(employee.hireDate)}</strong><small>{employee.vacationBalance} dias de férias</small></div><div><span>Desempenho</span><strong>{employee.performance}%</strong><small>Ciclo atual</small></div><div><span>Documentos</span><strong>6 válidos</strong><small>1 em revisão</small></div></div><div className="suite-tabs"><button className="active">Resumo</button><button>Assiduidade</button><button>Férias</button><button>Documentos</button><button>Histórico</button></div><div className="suite-modal-actions"><Button icon={Pencil} onClick={onClose}>Editar</Button>{employee.status === 'Arquivado' ? <Button variant="primary" onClick={()=>{onReactivate(employee.id);onClose()}}>Reativar</Button> : <Button variant="danger" icon={Archive} onClick={()=>{onArchive(employee.id);onClose()}}>Arquivar</Button>}</div></Modal>}
function CandidateForm({onClose,onSave}){const [form,setForm]=useState({name:'',role:'',stage:'Candidatura',score:80,source:'Site',experience:80,roleFit:80,interview:80,note:''});const patch=(key,value)=>setForm((current)=>({...current,[key]:value}));return <Modal title="Adicionar candidato" onClose={onClose}><form className="suite-form" onSubmit={(e)=>{e.preventDefault();onSave(form)}}><div className="suite-form-grid"><Field label="Nome" required><input value={form.name} onChange={(e)=>patch('name',e.target.value)} required/></Field><Field label="Função" required><input value={form.role} onChange={(e)=>patch('role',e.target.value)} required/></Field><Field label="Etapa"><select value={form.stage} onChange={(e)=>patch('stage',e.target.value)}><option>Candidatura</option><option>Triagem</option><option>Entrevista</option><option>Proposta</option><option>Contratado</option></select></Field><Field label="Origem"><select value={form.source} onChange={(e)=>patch('source',e.target.value)}><option>Site</option><option>LinkedIn</option><option>Referral</option><option>Indeed</option></select></Field></div><Field label="Notas"><textarea rows="4" value={form.note} onChange={(e)=>patch('note',e.target.value)}/></Field><div className="suite-modal-actions"><Button onClick={onClose}>Cancelar</Button><Button type="submit" variant="primary">Adicionar</Button></div></form></Modal>}
function CandidateDetail({candidate,onClose,onAdvance}){return <Modal title={`Candidato · ${candidate.name}`} onClose={onClose}><div className="suite-profile-head"><span className="suite-avatar xl">{initials(candidate.name)}</span><div><h3>{candidate.role}</h3><span>{candidate.source} · score profissional {candidate.score}</span></div></div><div className="suite-detail-grid"><div><span>Experiência</span><strong>{candidate.criteria.experience}%</strong><small>Histórico profissional</small></div><div><span>Aderência</span><strong>{candidate.criteria.roleFit}%</strong><small>Requisitos da função</small></div><div><span>Entrevista</span><strong>{candidate.criteria.interview}%</strong><small>Avaliação documentada</small></div><div><span>Próxima etapa</span><strong>{candidate.stage}</strong><small>{candidate.nextInterview ? formatDate(candidate.nextInterview) : 'Por definir'}</small></div></div><Card className="suite-note"><ShieldCheck size={16}/><span>{candidate.note}</span></Card><div className="suite-modal-actions"><Button onClick={()=>onAdvance('Triagem')}>Triagem</Button><Button onClick={()=>onAdvance('Entrevista')}>Entrevista</Button><Button variant="primary" onClick={()=>onAdvance('Proposta')}>Proposta</Button></div></Modal>}
function TaskForm({onClose,onSave}){const [form,setForm]=useState({title:'',owner:'Ana Martins',due:today(),priority:'Média'});return <Modal title="Nova tarefa de RH" onClose={onClose}><form className="suite-form" onSubmit={(e)=>{e.preventDefault();onSave(form)}}><Field label="Título" required><input value={form.title} onChange={(e)=>setForm({...form,title:e.target.value})} required/></Field><div className="suite-form-grid"><Field label="Responsável"><select value={form.owner} onChange={(e)=>setForm({...form,owner:e.target.value})}><option>Ana Martins</option><option>Bruno Almeida</option><option>Carolina Silva</option><option>Hugo Carvalho</option></select></Field><Field label="Prazo"><input type="date" value={form.due} onChange={(e)=>setForm({...form,due:e.target.value})}/></Field><Field label="Prioridade"><select value={form.priority} onChange={(e)=>setForm({...form,priority:e.target.value})}><option>Baixa</option><option>Média</option><option>Alta</option></select></Field></div><div className="suite-modal-actions"><Button onClick={onClose}>Cancelar</Button><Button type="submit" variant="primary">Criar tarefa</Button></div></form></Modal>}
function ShiftForm({onClose,onSave}){const [form,setForm]=useState({name:'',team:'Recursos Humanos',days:'Seg–Sex'});return <Modal title="Criar turno" onClose={onClose}><form className="suite-form" onSubmit={(e)=>{e.preventDefault();onSave(form)}}><Field label="Nome do turno" required><input value={form.name} onChange={(e)=>setForm({...form,name:e.target.value})} placeholder="Ex.: RH · 09:00–18:00" required/></Field><div className="suite-form-grid"><Field label="Equipa"><select value={form.team} onChange={(e)=>setForm({...form,team:e.target.value})}><option>Recursos Humanos</option><option>Operações</option><option>Tecnologia</option><option>Comercial</option></select></Field><Field label="Dias"><input value={form.days} onChange={(e)=>setForm({...form,days:e.target.value})}/></Field></div><div className="suite-modal-actions"><Button onClick={onClose}>Cancelar</Button><Button type="submit" variant="primary">Criar turno</Button></div></form></Modal>}
function VacationForm({employees,onClose,onSave}){const [form,setForm]=useState({employee:employees[0]?.name||'',type:'Férias',start:today(),end:today(),days:1});return <Modal title="Novo pedido" onClose={onClose}><form className="suite-form" onSubmit={(e)=>{e.preventDefault();onSave({...form,days:Number(form.days)})}}><div className="suite-form-grid"><Field label="Colaborador"><select value={form.employee} onChange={(e)=>setForm({...form,employee:e.target.value})}>{employees.map((employee)=><option key={employee.id}>{employee.name}</option>)}</select></Field><Field label="Tipo"><select value={form.type} onChange={(e)=>setForm({...form,type:e.target.value})}><option>Férias</option><option>Falta</option><option>Licença</option><option>Ausência</option></select></Field><Field label="Início"><input type="date" value={form.start} onChange={(e)=>setForm({...form,start:e.target.value})}/></Field><Field label="Fim"><input type="date" value={form.end} onChange={(e)=>setForm({...form,end:e.target.value})}/></Field><Field label="Dias"><input type="number" min="1" value={form.days} onChange={(e)=>setForm({...form,days:e.target.value})}/></Field></div><div className="suite-modal-actions"><Button onClick={onClose}>Cancelar</Button><Button type="submit" variant="primary">Submeter pedido</Button></div></form></Modal>}
function DocumentForm({employees,onClose,onSave}){const [form,setForm]=useState({employee:employees[0]?.name||'',type:'Contrato de trabalho',expiry:'2027-12-31'});return <Modal title="Carregar documento" onClose={onClose}><form className="suite-form" onSubmit={(e)=>{e.preventDefault();onSave(form)}}><Field label="Colaborador"><select value={form.employee} onChange={(e)=>setForm({...form,employee:e.target.value})}>{employees.map((employee)=><option key={employee.id}>{employee.name}</option>)}</select></Field><Field label="Tipo"><select value={form.type} onChange={(e)=>setForm({...form,type:e.target.value})}><option>Contrato de trabalho</option><option>Recibo</option><option>Certificado</option><option>Documento de identificação</option></select></Field><Field label="Validade"><input type="date" value={form.expiry} onChange={(e)=>setForm({...form,expiry:e.target.value})}/></Field><div className="suite-modal-actions"><Button onClick={onClose}>Cancelar</Button><Button type="submit" variant="primary">Guardar documento</Button></div></form></Modal>}
function GoalForm({employees,onClose,onSave}){const [form,setForm]=useState({employee:employees[0]?.name||'',title:'',cycle:'Q4 2026',owner:'Gestor RH',progress:0});return <Modal title="Novo objetivo" onClose={onClose}><form className="suite-form" onSubmit={(e)=>{e.preventDefault();onSave(form)}}><Field label="Objetivo" required><input value={form.title} onChange={(e)=>setForm({...form,title:e.target.value})} required/></Field><div className="suite-form-grid"><Field label="Colaborador"><select value={form.employee} onChange={(e)=>setForm({...form,employee:e.target.value})}>{employees.map((employee)=><option key={employee.id}>{employee.name}</option>)}</select></Field><Field label="Ciclo"><input value={form.cycle} onChange={(e)=>setForm({...form,cycle:e.target.value})}/></Field><Field label="Responsável"><input value={form.owner} onChange={(e)=>setForm({...form,owner:e.target.value})}/></Field></div><div className="suite-modal-actions"><Button onClick={onClose}>Cancelar</Button><Button type="submit" variant="primary">Criar objetivo</Button></div></form></Modal>}
